<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';

$eventId=max(0,(int)($_GET['event_id']??$_POST['event_id']??0)); $event=fetchEventById($pdo,$eventId);
if(!$event){http_response_code(404);$alerts[]=['type'=>'danger','message'=>'Event not found.'];admin_layout_start('Ride Notes','events');admin_layout_end();exit;}
ensureRideNotesTables($pdo); if(empty($_SESSION['ride_notes_csrf']))$_SESSION['ride_notes_csrf']=bin2hex(random_bytes(24)); $csrf=(string)$_SESSION['ride_notes_csrf']; $siteSettings=getSiteSettings($pdo); $notes=fetchRideNotes($pdo,$eventId)?:['status'=>'draft','intro_html'=>'','ride_notes_html'=>'','ctr_notes_html'=>'']; $batch=mediaBatchGetOrCreate($pdo,'ride_notes_images','event',$eventId,'Ride Notes images: '.(string)$event['title'],'ride-notes');
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))) $alerts[]=['type'=>'danger','message'=>'Your session token expired. Please try again.'];
    else { $action=(string)($_POST['action']??'');
        if($action==='save'){if(saveRideNotes($pdo,$eventId,$_POST,(int)$currentUser['id'])){$_SESSION['flash_success']='Ride Notes saved.';header('Location: ride_notes.php?event_id='.$eventId);exit;}$alerts[]=['type'=>'danger','message'=>'Ride Notes could not be saved.'];}
        elseif($action==='upload_images'){$errors=[];$count=mediaBatchUpload($pdo,$batch,$_FILES['images']??[],['original'=>null,'lg'=>1400,'md'=>800,'sm'=>400,'xs'=>180],$errors);foreach($errors as $error)$alerts[]=['type'=>'danger','message'=>$error];if($count){$_SESSION['flash_success']=$count.($count===1?' image uploaded.':' images uploaded.');header('Location: ride_notes.php?event_id='.$eventId);exit;}}
        elseif($action==='upload_pdf'){$error=null;$stored=rideNotesStorePdf($_FILES['ride_notes_pdf']??[],$event,$error);if(!$stored)$alerts[]=['type'=>'danger','message'=>$error?:'Unable to upload the Ride Notes PDF.'];elseif(saveRideNotesPdf($pdo,$eventId,$stored)){$_SESSION['flash_success']='Ride Notes PDF uploaded.';header('Location: ride_notes.php?event_id='.$eventId);exit;}else $alerts[]=['type'=>'danger','message'=>'The PDF was uploaded but could not be recorded.'];}
        elseif($action==='send_test'){$recipients=parseEmailList((string)($_POST['test_recipients']??''));if(($notes['status']??'draft')!=='published')$alerts[]=['type'=>'warning','message'=>'Publish the Ride Notes before sending a full email test. Use Preview while they are still a draft.'];elseif(!$recipients)$alerts[]=['type'=>'danger','message'=>'Enter one or more valid test email addresses.'];else{$settings=getEmailSettings($pdo);$payload=rideNotesEmailPayload($event,$notes,$siteSettings,$settings,$siteBase);$attachment=rideNotesPdfAttachment($notes);$sent=0;foreach($recipients as $recipient)if(send_logged_email($pdo,$recipient,$payload['subject'],$payload['html'],$payload['text'],['kind'=>'ride_notes_test','event_id'=>$eventId,'admin_user_id'=>(int)$currentUser['id']],$attachment?[$attachment]:[]))$sent++;$alerts[]=['type'=>$sent===count($recipients)?'success':'warning','message'=>$sent.' of '.count($recipients).' test email'.(count($recipients)===1?' was':'s were').' sent. Check Email logs for details.'];}}
        elseif($action==='create_campaign'){
            if(($notes['status']??'draft')!=='published')$alerts[]=['type'=>'warning','message'=>'Publish the Ride Notes before creating its campaign.'];
            else{
                ensureEmailCampaignTables($pdo);$templateStmt=$pdo->prepare("SELECT * FROM email_campaign_templates WHERE template_key='ride_notes' LIMIT 1");$templateStmt->execute();$campaignTemplate=$templateStmt->fetch()?:[];
                $campaignSubject=(string)($campaignTemplate['subject_template']??'Ride Notes: {{event_title}}');
                $campaignHtml=(string)($campaignTemplate['html_template']??'<h2>Ride Notes</h2><p>Hello {{first_name}},</p><p>Important information for <strong>{{event_title}}</strong> on {{event_date}} is now available.</p><p><a href="{{ride_notes_url}}">View Ride Notes</a></p>');
                $campaignText=(string)($campaignTemplate['text_template']??"Ride Notes\n\nHello {{first_name}},\n\nImportant information for {{event_title}} on {{event_date}} is now available.\n\n{{ride_notes_url}}");
                $existing=$pdo->prepare("SELECT id FROM email_campaigns WHERE campaign_type='ride_notes' AND event_id=:event AND status NOT IN ('cancelled','sent') ORDER BY id DESC LIMIT 1");$existing->execute([':event'=>$eventId]);$campaignId=(int)($existing->fetchColumn()?:0);
                if(!$campaignId){$stmt=$pdo->prepare("INSERT INTO email_campaigns (name,campaign_type,category,template_id,audience_preset,event_id,membership_year,address_strategy,subject_template,html_template,text_template,batch_size,created_by_user_id) VALUES (:name,'ride_notes','operational',:template,'event_entrants',:event,:year,'person_first',:subject,:html,:text,:batch,:user)");$stmt->execute([':name'=>'Ride Notes - '.(string)$event['title'],':template'=>(int)($campaignTemplate['id']??0)?:null,':event'=>$eventId,':year'=>(int)date('Y'),':subject'=>$campaignSubject,':html'=>$campaignHtml,':text'=>$campaignText,':batch'=>max(1,(int)($siteSettings['campaign_default_batch_size']??25)),':user'=>(int)$currentUser['id']]);$campaignId=(int)$pdo->lastInsertId();}
                header('Location: campaigns.php?view=edit&id='.$campaignId);exit;
            }
        }
    } $notes=array_merge($notes,$_POST);
}
$images=$batch?mediaBatchImages($pdo,(int)$batch['id']):[];$defaultIntro=rideNotesDefaultSettings($siteSettings)['intro_html'];admin_layout_start('Ride Notes','events');
?>
